(()=>{
 const cwd=process.cwd()+'/_scratch/ar-final/recovery-workspace';
 const parent=ltManager.getAllInstances().find(i=>i.parentId===null&&i.provider==='codex');
 const children=ltManager.getAllInstances().filter(i=>i.parentId===parent?.id);
 if(!parent||children.length!==2||!parent.providerSessionPersisted)throw Error('Parent/conversation or child fixture not ready');
 if(children.some(i=>i.status!=='busy'||!ltManager.getAdapter(i.id)?.appServerRuntime?.hasActiveTurn?.()))throw Error('Both real children must have active turns');
 globalThis.ltAr2={parentId:parent.id,liveId:children[0].id,deadId:children[1].id,cwd,mainPid:process.pid,armedAt:Date.now(),matches:[],responses:[],stage:'armed'};
 const lifecycle=ltManager.lifecycle,old=lifecycle.createRuntimeAdapter;
 lifecycle.createRuntimeAdapter=async function(...args){
  const adapter=await old.apply(this,args);const options=args[1];
  if(args[0]==='codex'&&options.instanceId===ltAr2.parentId&&options.workingDirectory===cwd&&options.resume===true&&ltAr2.matches.length===0){
   const receipt={at:Date.now(),resume:options.resume,instanceId:options.instanceId,workspaceMatches:options.workingDirectory===cwd};ltAr2.matches.push(receipt);
   const spawn=adapter.spawn;
   adapter.spawn=async function(){
    adapter.spawn=spawn;const start=Date.now();receipt.spawnAt=start;
    while(Date.now()-start<15000){
     const suppressed=ltManager.getOrchestrationHandler().suppressedChildCompletions.get(ltAr2.parentId)?.has(ltAr2.deadId)===true;
     if(suppressed){receipt.suppressionObservedAt=Date.now();receipt.parentStatus=ltManager.getInstance(ltAr2.parentId)?.status;break;}
     await new Promise(r=>setTimeout(r,100));
    }
    receipt.suppressionObserved=!!receipt.suppressionObservedAt;
    receipt.thrownAt=Date.now();throw Error('AR002 fixture: one scoped native resume refusal after child completion window');
   };
  }
  return adapter;
 };
 globalThis.ltAr2Restore=()=>{lifecycle.createRuntimeAdapter=old;};
 const handler=ltManager.getOrchestrationHandler();
 globalThis.ltAr2ResponseListener=(id,response)=>{if(id===ltAr2.parentId&&ltAr2.stage==='query'&&/get_children|get_child_summary/.test(response))ltAr2.responses.push({at:Date.now(),response});};
 handler.on('inject-response',ltAr2ResponseListener);
 const snapshot={at:Date.now(),cwd,mainPid:process.pid,parent:{id:parent.id,pid:parent.processId,adapterPid:ltManager.getAdapter(parent.id).appServerRuntime.getPid(),provider:parent.provider},live:{id:children[0].id,pid:children[0].processId,provider:children[0].provider,parentId:children[0].parentId},dead:{id:children[1].id,pid:children[1].processId,provider:children[1].provider,parentId:children[1].parentId}};
 ltRequire('node:fs').writeFileSync(process.cwd()+'/docs/plans/2026-09-27-livetest-agent-runtime-residuals_evidence/2026-10-27-verifier-repair/ar002-owned-pids.json',JSON.stringify(snapshot,null,2));
 return {at:Date.now(),armed:true,...snapshot};
})()

(async()=>{
 const task="Authorized disposable recovery test. Do not read or edit files, create documents, or spawn helpers. Run eighteen separate foreground calls of the exact command rtk proxy sleep 20, one after another. Wait for each call before starting the next, and do not combine them into one longer command. If a call returns a session, poll that same session until it exits. Keep working until all eighteen waits have completed (at least six minutes). Do not background anything. Then reply WAIT_COMPLETE.";
 const block=name=>':::ORCHESTRATOR_COMMAND:::\n'+JSON.stringify({action:'spawn_child',provider:'codex',model:'gpt-5.6-terra',yoloMode:true,name,task})+'\n:::END_COMMAND:::';
 const prompt='This is an authorized isolated recovery test. Print the following TWO command blocks as plain response text exactly once, without fences or tool calls yourself. They create two real background children through Harness. Then reply PARENT_READY and wait. Never emit spawn_child again on any later input, recovery, or continuity notice.\n\n'+block('AR002 child A')+'\n\n'+block('AR002 child B');
 const r=await window.electronAPI.createInstance({workingDirectory:location.hostname==='localhost'?'/Users/suas/work/orchestrat0r/ai-orchestrator/.worktrees/queue/2026-09-27-livetest-agent-runt-f326de/_scratch/ar-final/recovery-workspace':'',provider:'codex',model:'gpt-5.6-sol',yoloMode:true,browserToolsMode:'off',initialPrompt:prompt});
 if(!r.success)throw Error(JSON.stringify(r));window.ltAr2Parent=r.data.id;
 return {at:Date.now(),id:r.data.id,provider:r.data.provider,status:r.data.status};
})()

(()=>{
 const p=ltManager.getInstance(ltAr2.parentId),h=ltManager.getOrchestrationHandler();
 const queued=ltManager.communication.continuityInputQueue.continuityPreambles.get(ltAr2.parentId)?.value??'';
 const start=queued.indexOf('[SESSION DEGRADATION NOTICE]'),end=queued.indexOf('[END SESSION DEGRADATION NOTICE]');
 const notice=start>=0&&end>=start?queued.slice(start,end+'[END SESSION DEGRADATION NOTICE]'.length):null;
 const result={at:Date.now(),parent:{id:p?.id,status:p?.status,pid:p?.processId},matches:ltAr2.matches,notice,liveNamedAttached:!!notice?.includes(ltAr2.liveId),deadNamedLost:!!notice?.includes(ltAr2.deadId),completed:h.getCompletedChildIds(ltAr2.parentId),instances:ltManager.getAllInstances().map(i=>({id:i.id,parentId:i.parentId,status:i.status,pid:i.processId})),responses:ltAr2.responses};
 ltRequire('node:fs').writeFileSync(process.cwd()+'/docs/plans/2026-09-27-livetest-agent-runtime-residuals_evidence/2026-10-27-verifier-repair/ar002-recovery-state.json',JSON.stringify(result,null,2));
 return result;
})()

import {spawn} from 'node:child_process';
import {openSync,appendFileSync} from 'node:fs';
const [name,...argv]=process.argv.slice(2);
const dir='docs/plans/2026-09-27-livetest-agent-runtime-residuals_evidence/2026-10-27-verifier-repair';
const start=new Date().toISOString();
const fd=openSync(dir+'/'+name+'.txt','w');
const child=spawn('rtk',['proxy',...argv],{stdio:['ignore',fd,fd],detached:process.platform!=='win32'});
appendFileSync(dir+'/command-starts.jsonl',JSON.stringify({start,argv,runnerPid:process.pid,childPid:child.pid,node:process.version,execPath:process.execPath,log:name+'.txt'})+'\n');
process.on('SIGTERM',()=>{process.kill(process.platform==='win32'?child.pid:-child.pid,'SIGTERM');});
child.on('error',e=>{console.error(e.message);process.exitCode=1;});
child.on('exit',(code,signal)=>{appendFileSync(dir+'/commands.jsonl',JSON.stringify({start,end:new Date().toISOString(),argv,code,signal,log:name+'.txt'})+'\n');console.log(name+': exit '+code);process.exitCode=code??1;});

import {createServer} from 'node:http';
import {readFileSync,statSync,openSync,writeFileSync} from 'node:fs';
import {resolve,extname,sep} from 'node:path';
import {spawn} from 'node:child_process';
const here=process.cwd(),dir=here+'/_scratch/ar-final',root=resolve(here,'dist/renderer/browser');
const types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.svg':'image/svg+xml','.woff2':'font/woff2','.png':'image/png','.ico':'image/x-icon'};
const server=createServer((req,res)=>{
 let path=resolve(root,'.'+new URL(req.url,'http://localhost').pathname);
 if(path!==root&&!path.startsWith(root+sep)){res.writeHead(403);res.end();return;}
 try{if(!statSync(path).isFile())path=resolve(root,'index.html');}catch{path=resolve(root,'index.html');}
 res.setHeader('Content-Type',types[extname(path)]??'application/octet-stream');res.end(readFileSync(path));
});
await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(4735,'127.0.0.1',resolve);});
let app;
try{
 const log=openSync(dir+'/recovery-electron.log','w');
 app=spawn(here+'/node_modules/electron/dist/Electron.app/Contents/MacOS/Electron',['.','--no-sandbox','--js-flags=--max-old-space-size=8192','--remote-debugging-port=9735','--inspect=9736'],{cwd:here,env:{...process.env,AIO_DEV_USER_DATA_PATH:'/tmp/aio-lt-queue-3af326de',PORT:'4735'},stdio:['ignore',log,log]});
 writeFileSync(dir+'/recovery-processes.json',JSON.stringify({at:new Date().toISOString(),supervisor:process.pid,app:app.pid,renderer:'already-built static renderer in supervisor'}));
 await new Promise((resolve,reject)=>{app.once('exit',resolve);app.once('error',reject);});
}finally{
 if(app&&app.exitCode===null&&app.signalCode===null)app.kill('SIGTERM');
 await new Promise(resolve=>server.close(resolve));
 writeFileSync(dir+'/recovery-process-exit.json',JSON.stringify({at:new Date().toISOString(),pid:app?.pid,code:app?.exitCode,signal:app?.signalCode,serverClosed:true}));
}
